package local.lito381.server;
/** First BATTLE owner/audience proof follows the original companion clock; no worker, registry or new lock. */
final class NativeSourceCompanionClock {
 static Object capture(GameHub hub,Object room,ClientSession owner){var b=NativeSourceNpcPlayerView.start(hub,room);NativeSourceNpcPlayerView.remember(owner,b);return NativeSourceNpcPlayerView.finish(owner,b);}
 static boolean valid(ClientSession owner,long room,Object choice){if(choice==null)return true;if(choice instanceof ClientSession old)return old==owner;return choice instanceof NativeSourceNpcPlayer.Origin o&&o.primary()==owner&&o.room()==room&&CombatAccess.field(owner,"hub")==o.hub()&&NativeSourceNpcPlayerView.current(o);}
 static boolean ready(ClientSession owner,BattleCompanion pet,long room,Object choice){if(!valid(owner,room,choice))return false;if(!(choice instanceof NativeSourceNpcPlayer.Origin))return true;return pet!=null&&CombatAccess.call(owner,"ownedCompanion","(J)Llocal/lito381/server/BattleCompanion;",(long)CombatAccess.field(pet,"objectId"))==pet;}
 static NativeCombatAttacker.Ref ref(ClientSession owner,BattleCompanion pet,Object choice){var ref=NativeCombatAttacker.companion(owner,pet);if(!(choice instanceof NativeSourceNpcPlayer.Origin o))return ref;return valid(owner,o.room(),o)?NativeSourceNpcOrigins.stamp(ref,o.original()):null;}
 static Object attach(Object ingress,ClientSession owner,GameHub.MonsterAiTick tick,BattleCompanion pet,Object choice){if(ingress==null)return null;try{if(choice instanceof NativeSourceNpcPlayer.Origin o&&!ready(owner,pet,o.room(),choice)){CombatAccess.set(ingress,"nativeSourceNpcPlayerScope",Boolean.FALSE);return ingress;}return NativeSourceNpcPlayer.nativeSourceCompanionClockAttach(ingress,owner,tick,pet,choice);}catch(RuntimeException failure){CombatAccess.set(ingress,"nativeSourceNpcPlayerScope",Boolean.FALSE);NativeSourcePhysicalNpc.failed(NativePlayerLifetime.of((GameHub)CombatAccess.field(owner,"hub")));return ingress;}}
 static NativeSourceNpcPlayer.Origin origin(ClientSession owner,NativeSourceRawDamage.Member member,GameHub hub,long room,Object choice){if(!(choice instanceof NativeSourceNpcPlayer.Origin o))return NativeSourceNpcPlayer.capture(owner,member,hub,room);return o.primary()==owner&&o.hub()==hub&&o.room()==room&&o.original()!=null&&o.original().binding.equals(member.binding)&&o.original().life==member.life?o:new NativeSourceNpcPlayer.Origin(hub,-1,owner,member,java.util.Map.of());}
 static boolean selected(boolean playerTarget,ClientSession target,Object choice){if(!playerTarget||!(choice instanceof NativeSourceNpcPlayer.Origin o))return true;var m=o.members().get(target);return m!=null&&m.binding.phase().equals("BATTLE")&&m.binding.room()==o.room()&&CombatAccess.field(target,"hub")==o.hub()&&m.current(false);}
 private NativeSourceCompanionClock(){}
}
